package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamMediaCivilBank1 {
  private const val T = "ජනමාධ්‍ය, මහජන මතය, වැඩ ලෝකය හා සිවිල් සමාජය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පොදු ජනතාවගේ ප්‍රශ්න හා අවශ්‍යතා සම්බන්ධයෙන් බහුතර පුරවැසියන් තුළ ගොඩනැගෙන සාමූහික ආකල්පය හඳුන්වන්නේ කුමන නමින්ද?", "මහජන මතය (Public Opinion)", "රාජ්‍ය රහස්‍යභාවය", "ව්‍යවස්ථා සභාව", "අධිකරණ පූර්වාදර්ශය", "ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයක ප්‍රතිපත්ති සම්පාදනයට හා පාලනයට මහජන මතය සෘජුව බලපෑම් කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී පාලන ක්‍රමයක ව්‍යවස්ථාදායකය, විධායකය හා අධිකරණයට අමතරව 'සිව්වන ආණ්ඩුව' (Fourth Estate) ලෙස හඳුන්වන්නේ කුමක්ද?", "ජනමාධ්‍යය", "පළාත් පාලන ආයතන", "මහ බැංකුව", "විගණකාධිපති දෙපාර්තමේන්තුව", "එඩ්මන්ඩ් බර්ක් හඳුන්වා දුන් පරිදි ජනමාධ්‍යය රජයේ ක්‍රියාකලාපය විවේචනාත්මකව අධීක්ෂණය කරන මුරකරුවෙකි."),
    q("සෞඛ්‍ය සම්පන්න 'මහජන මතයක්' ගොඩනැගීම සඳහා පුරවැසියන්ට අනිවාර්යයෙන්ම තිබිය යුතු මූලික ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකම කුමක්ද?", "අදහස් ප්‍රකාශ කිරීමේ නිදහස හා නිවැරදි තොරතුරු දැනගැනීමේ අයිතිය", "සියලු පුවත්පත් වාරණය කිරීම", "අන්තර්ජාලය තහනම් කිරීම", "විරුද්ධ මත දරන්නන් සිරගත කිරීම", "නිදහස් මාධ්‍ය හා විවෘත විවාද නොමැති තැන සැබෑ මහජන මතයක් ප්‍රකාශයට පත් නොවේ."),
    q("පුවත්පත්, සඟරා, ග්‍රන්ථ සහ පත්‍රිකා අයත් වන්නේ කුමන ජනමාධ්‍ය ප්‍රභේදයටද?", "මුද්‍රිත ජනමාධ්‍ය (Print Media)", "විද්‍යුත් විකාශන මාධ්‍ය", "සමාජ මාධ්‍ය ජාල", "ශ්‍රව්‍ය දෘශ්‍ය මාධ්‍ය", "විධිමත් හා ස්ථිර ලිඛිත වාර්තා ලෙස පවතින මුද්‍රිත මාධ්‍ය විචාරශීලී කියවීමට පහසුය."),
    q("ශ්‍රී ලංකාවේ පළමු සිංහල පුවත්පත ලෙස 1860 වසරේදී ආරම්භ කෙරුණේ කුමන පුවත්පතද?", "ලංකාලෝකය (ගාල්ල)", "දිනමිණ", "සිළුමිණ", "ලක්මිණි පහණ", "1860 දී ගාල්ලෙන් ලංකාලෝකය ආරම්භ වූ අතර 1862 දී කොළඹින් ලක්මිණි පහණ ප්‍රකාශයට පත් විය."),
    q("ගුවන්විදුලිය හා රූපවාහිනිය අයත් වන ජනමාධ්‍ය වර්ගය හඳුන්වන්නේ කුමන නමින්ද?", "විද්‍යුත් විකාශන මාධ්‍ය (Electronic Media)", "මුද්‍රිත මාධ්‍ය", "සාම්ප්‍රදායික ජන සන්නිවේදන මාධ්‍ය", "අත්පත්‍රිකා මාධ්‍ය", "දුර බැහැර හා අකුරු නොදත් ජනතාව වෙත පවා ක්ෂණිකව තොරතුරු ගෙන යාමේ හැකියාව විද්‍යුත් මාධ්‍ය සතුය."),
    q("අන්තර්ජාලය, වෙබ් අඩවි, යූටියුබ් හා සමාජ ජාල වේදිකා හඳුන්වන පොදු නාමය කුමක්ද?", "නව මාධ්‍ය හෙවත් ඩිජිටල් මාධ්‍ය (New / Digital Media)", "මුද්‍රිත මාධ්‍ය", "පුස්තකාල මාධ්‍ය", "තැපැල් මාධ්‍ය", "සෑම පුරවැසියෙකුටම පණිවිඩ ලබාගැනීමට මෙන්ම නිර්මාණය කර බෙදාහැරීමටද නව මාධ්‍ය ඉඩ සලසයි."),
    q("සාම්ප්‍රදායික ජනමාධ්‍ය සහ නව සමාජ මාධ්‍ය අතර ඇති ප්‍රධාන වෙනස්කම කුමක්ද?", "නව මාධ්‍ය තුළ ග්‍රාහකයාට ක්ෂණිකව ප්‍රතිචාර දැක්වීමේ හා අන්තර්ගත නිර්මාණයේ ද්වි-මාර්ගික හැකියාව පැවතීම", "මුද්‍රිත මාධ්‍ය තුළ කියවීමට නොහැකි වීම", "නව මාධ්‍ය අන්තර්ජාලය නැතිව ක්‍රියා කිරීම", "රූපවාහිනිය මුද්‍රිත මාධ්‍යයක් වීම", "අන්තර්ක්‍රියාකාරී බව (Interactivity) නව මාධ්‍යයේ ප්‍රධාන ලක්ෂණයකි."),
    q("සාමාන්‍ය පුරවැසියෙකු තම ජංගම දුරකථනය මඟින් පොදු සිදුවීමක් වාර්තා කර සමාජය සමඟ බෙදාගැනීම හඳුන්වන්නේ කෙසේද?", "පුරවැසි පත්‍රකලාවේදය (Citizen Journalism)", "රාජ්‍ය වාරණය", "මුද්‍රණ කලාව", "ඒකාධිකාරී විකාශනය", "දුරස්ථ ප්‍රදේශවල සිදුවන පාරිසරික හානි හෝ ප්‍රජා ගැටලු ඉක්මනින් හෙළි කිරීමට පුරවැසි පත්‍රකලාව උපකාරී වේ."),
    q("මාධ්‍ය පණිවිඩයක් දුටු පමණින් නොරැවටී එහි සත්‍යතාව, මූලාශ්‍රය හා යටි අරමුණ විමසා බැලීමේ හැකියාව කුමක්ද?", "මාධ්‍ය සාක්ෂරතාව (Media Literacy)", "මුද්‍රණ දෝෂ පරීක්ෂාව", "දැන්වීම් නිර්මාණය", "ගුවන්විදුලි තාක්ෂණය", "මාධ්‍ය සාක්ෂරතාව ඇති පුරවැසියා ව්‍යාජ පුවත්වලින් හා කටකතාවලින් ආරක්ෂා වේ."),
    q("වැරදීමකින් හෝ නොදැනුවත්කමින් සමාජගත වන සාවද්‍ය තොරතුරු හා සිතාමතාම අන් අය නොමඟ යැවීමට නිපදවන අසත්‍ය තොරතුරු පිළිවෙළින් මොනවාද?", "සාවද්‍ය තොරතුරු (Misinformation) සහ දුෂ්තොරතුරු (Disinformation)", "සත්‍ය පුවත් සහ ගැසට් නිවේදන", "විශේෂාංග සහ කතුවැකි", "විගණන වාර්තා සහ ටෙන්ඩර්", "අසත්‍ය තොරතුරු පතුරුවා හැරීමේ චේතනාව අනුව මෙම වර්ගීකරණය සිදු කෙරේ."),
    q("සමාජ මාධ්‍ය හරහා සැකසහිත පුවතක් බෙදාගැනීමට (Share කිරීමට) පෙර පුරවැසියෙකු අනිවාර්යයෙන් කළ යුතු පරීක්ෂාව කුමක්ද?", "විශ්වාසදායක ප්‍රවෘත්ති මූලාශ්‍ර කිහිපයකින් එහි සත්‍යතාව හා දිනය තහවුරු කර ගැනීම (Fact-Checking)", "ශීර්ෂපාඨය පමණක් බලා ක්ෂණිකව යැවීම", "හිතවතුන්ගෙන් කටකතා ඇසීම", "අමතර බියකරු වචන එක් කර යැවීම", "තහවුරු නොකළ පුවත් බෙදාහැරීම සමාජ කලබල හා ප්‍රචණ්ඩත්වයට මග පාදයි."),
    q("කිසියම් ජනමාධ්‍යයක් සත්‍ය කරුණු වෙනුවට ආවේගශීලී, අතිශයෝක්ති හා අපහාසාත්මක ශීර්ෂපාඨ යොදා පාඨකයන් ඇද ගැනීමේ ක්‍රමය කුමක්ද?", "කහ පත්‍රකලාවේදය (Yellow Journalism)", "ගවේෂණාත්මක පත්‍රකලාවේදය", "සංවර්ධන සන්නිවේදනය", "විද්‍යාත්මක පත්‍රකලාවේදය", "සදාචාරය පසෙකලා විකුණුම් හා Views වැඩි කර ගැනීමට කහ පත්‍රකලාව ක්‍රියා කරයි."),
    q("රාජ්‍ය දූෂණ, පරිසර විනාශ හෝ මහජන මුදල් අවභාවිතයන් ගැඹුරින් සාක්ෂි සහිතව සොයා බලා හෙළි කරන මාධ්‍ය භාවිතය කුමක්ද?", "ගවේෂණාත්මක පත්‍රකලාවේදය (Investigative Journalism)", "කහ පත්‍රකලාවේදය", "වෙළඳ ප්‍රචාරණය", "විනෝදාස්වාද කලාව", "සාක්ෂි හා දත්ත මත පදනම්ව සමාජයේ සැඟවුණු අසාධාරණ හෙළි කිරීම ප්‍රජාතන්ත්‍රවාදය ශක්තිමත් කරයි."),
    q("වෛෂයික වාර්තාකරණය (Objective Reporting) සහ ප්‍රචාරණවාදය (Propaganda) අතර ප්‍රධාන වෙනස කුමක්ද?", "වෛෂයික වාර්තාකරණය දෙපාර්ශ්වයේම කරුණු සමබරව දක්වන අතර ප්‍රචාරණවාදය එක් පාර්ශ්වයක අරමුණකට මතය හසුරුවයි", "දෙකම බොරු තොරතුරු නිපදවයි", "ප්‍රචාරණවාදය සැමවිටම විද්‍යාත්මකය", "වෛෂයික වාර්තාකරණය සාක්ෂි නොසලකයි", "ගුණාත්මක පත්‍රකලාවේදියෙකු තම පෞද්ගලික පක්ෂග්‍රාහීත්වය පසෙක තබා සත්‍ය කරුණු ඉදිරිපත් කරයි."),
    q("මාධ්‍ය ආචාරධර්ම අනුව ප්‍රවෘත්තියක යම් පුද්ගලයෙකුට චෝදනාවක් එල්ල වන විට එම පුද්ගලයාට හිමිවිය යුතු මූලික අයිතිය කුමක්ද?", "පිළිතුරු දීමේ හා නිවැරදි කිරීමේ අයිතිය (Right of Reply)", "වාර්තාකරුට පහර දීමේ අයිතිය", "පුවත්පත් ආයතනය වැසීමේ අයිතිය", "නිහඬව සිටීමට බල කිරීම", "දෙපාර්ශ්වයටම සවන් දීම ස්වාභාවික යුක්තියේ හා මාධ්‍ය ආචාරධර්මයේ අනිවාර්ය අංගයකි."),
    q("ළමා අපයෝජන හෝ අපරාධ සිදුවීම් වාර්තා කිරීමේදී ජනමාධ්‍ය විසින් අනිවාර්යයෙන්ම රැකිය යුතු ආචාරධර්මය කුමක්ද?", "වින්දිත දරුවාගේ හෝ පුද්ගලයාගේ නම, ඡායාරූපය හා අනන්‍යතාව හෙළි නොකර ගෞරවය රැකීම", "සම්පූර්ණ විස්තර හා පාසල ප්‍රචාරය කිරීම", "මුහුණ විශාල කර පෙන්වීම", "වින්දිතයාට දොස් පැවරීම", "දරුවන්ගේ අනාගතය හා මානසික ආරක්ෂාව වෙනුවෙන් ඔවුන්ගේ පෞද්ගලිකත්වය ආරක්ෂා කිරීම නීතිමය හා සදාචාර වගකීමකි."),
    q("ශ්‍රී ලංකාවේ පුවත්පත් ක්ෂේත්‍රයේ මාධ්‍ය ආචාරධර්ම ආරක්ෂා කර පැමිණිලි සමථයකට පත් කිරීමට 2003 දී මාධ්‍ය ආයතන එක්ව පිහිටුවූ ස්වයං-නියාමන ආයතනය කුමක්ද?", "ශ්‍රී ලංකා පුවත්පත් පැමිණිලි කොමිසම (PCCSL)", "ශ්‍රී ලංකා මහ බැංකුව", "පාරිභෝගික කටයුතු අධිකාරිය", "විගණකාධිපති දෙපාර්තමේන්තුව", "රජයේ බලහත්කාරී පාලනයකින් තොරව පුවත්පත් කර්මාන්තය විසින්ම පිහිටුවූ ස්වේච්ඡා ස්වයං-නියාමන ආයතනය මෙයයි."),
    q("1973 අංක 5 දරන පනත යටතේ රජය විසින් පිහිටුවනු ලැබූ ව්‍යවස්ථාපිත මුද්‍රිත මාධ්‍ය ආයතනය කුමක්ද?", "ශ්‍රී ලංකා පුවත්පත් මණ්ඩලය (Sri Lanka Press Council)", "තොරතුරු දැනගැනීමේ කොමිසම", "රාජ්‍ය සේවා කොමිසම", "සමථ මණ්ඩල කොමිසම", "ව්‍යවස්ථාපිත නීති මත පදනම්ව පුවත්පත් සම්බන්ධ පැමිණිලි විභාග කිරීමට මෙම මණ්ඩලය පිහිටුවන ලදී."),
    q("ජනමාධ්‍ය ක්ෂේත්‍රයේ 'ස්වයං-නියාමනය' (Self-Regulation) රාජ්‍ය මාධ්‍ය වාරණයට වඩා ප්‍රජාතන්ත්‍රවාදී වන්නේ ඇයි?", "රජයේ දේශපාලන මැදිහත්වීමකින් තොරව මාධ්‍ය නිදහසත් වගකීමත් එකවර සුරැකෙන බැවිනි", "කිසිදු නීතියක් නොමැති නිසා", "බොරු පුවත් පළ කිරීමට ඉඩ දෙන නිසා", "පුවත්පත් වසා දැමිය හැකි නිසා", "මාධ්‍යවේදීන්ගේ වෘත්තීය ආචාරධර්ම මත පදනම් වූ ස්වයං-පාලනය මාධ්‍ය ස්වාධීනත්වය රැකගනී."),
    q("1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 14(1)(අ) වගන්තියෙන් සහතික කර ඇති මාධ්‍ය නිදහසට පදනම් වන මූලික අයිතිවාසිකම කුමක්ද?", "භාෂණයේ හා ප්‍රකාශනයේ නිදහස (Freedom of Speech and Expression)", "සංචරණ නිදහස", "ආගමික නිදහස", "වෘත්තීය සමිති නිදහස", "සියලු ප්‍රකාශන නිදහසේ පදනම 14(1)(අ) වන අතර 15(2) හා 15(7) වගන්ති යටතේ නීත්‍යානුකූල සීමා පමණක් පැනවිය හැක."),
    q("පුවත්පතක ප්‍රධාන වශයෙන් පාඨක අදහස් හා ආයතනයේ නිල ස්ථාවරය පළ කරන තීරුව හඳුන්වන්නේ කුමන නමින්ද?", "කතුවැකිය (Editorial)", "වර්ගීකරණ දැන්වීම", "කාලගුණ වාර්තාව", "මරණ දැන්වීම", "දවසේ ප්‍රධාන සමාජ හෝ දේශපාලන ගැටලුවක් ගැන පුවත්පතේ විශ්ලේෂණාත්මක මතය කතුවැකියෙන් දැක්වේ."),
    q("වර්තමානයේ ඩිජිටල් අවකාශයේ පැතිරෙන 'ගැඹුරු ව්‍යාජ වීඩියෝ' (Deepfakes) යනු කුමක්ද?", "කෘත්‍රිම බුද්ධිය යොදාගෙන යම් අයෙකු නොකී හෝ නොකළ දෙයක් සත්‍ය ලෙස පෙන්වීමට සැකසූ ව්‍යාජ වීඩියෝ හා හඬපට", "සජීවී පාර්ලිමේන්තු විකාශන", "විශ්වවිද්‍යාල දේශන පටිගත කිරීම්", "රජයේ ගැසට් නිවේදන", "නවීන තාක්ෂණය හමුවේ පුරවැසියන් ඩිජිටල් සාක්ෂරතාවයෙන් යුතුව මූලාශ්‍ර පරීක්ෂා කිරීම අතිශය වැදගත් වේ."),
    q("සමාජ මාධ්‍ය වේදිකාවල 'ඇල්ගොරිතම බුබුළු' (Filter Bubbles / Echo Chambers) මඟින් මහජන මතයට ඇතිවන අහිතකර බලපෑම කුමක්ද?", "පුද්ගලයා කැමති මතයම පමණක් නැවත නැවත පෙන්වීමෙන් විරුද්ධ මත නොසලකා හරින අන්තගාමී බවක් ඇතිවීම", "සියලු පාසල් පෙළපොත් නොමිලේ ලැබීම", "විදුලි බිල අඩු වීම", "සියලු ජන කොටස් අතර සමගිය ඉබේම ඇති වීම", "විවිධ පුවත්පත් හා සමබර මූලාශ්‍ර කියවීමෙන් මෙම පටු මානසික සීමාවෙන් මිදිය හැක."),
    q("පෞද්ගලික ජනමාධ්‍ය ආයතන තම පුවත් ඉදිරිපත් කිරීමේදී මහජන යහපතට වඩා ආර්ථික හෝ දේශපාලන වාසි සැලකීමට හේතුව කුමක්ද?", "මාධ්‍ය හිමිකාරිත්වයේ පක්ෂග්‍රාහීත්වය හා වාණිජ දැන්වීම් මත යැපීම", "මාධ්‍ය සාක්ෂරතාව අධික වීම", "රාජ්‍ය විගණනය ක්‍රියාත්මක වීම", "පුස්තකාල වැඩි වීම", "මාධ්‍ය හිමිකාරිත්වයේ විනිවිදභාවය හා මහජන සේවා විකාශන (Public Service Broadcasting) ස්වාධීන වීම වැදගත්ය."),
    q("මැතිවරණ කාලසීමාවකදී ජනමාධ්‍ය විසින් ඉටු කළ යුතු ප්‍රධාන ප්‍රජාතන්ත්‍රවාදී වගකීම කුමක්ද?", "සියලු පක්ෂවලට හා අපේක්ෂකයන්ට සමාන අවස්ථා දී අපක්ෂපාතී තොරතුරු ඡන්දදායකයාට සැපයීම", "එක් අපේක්ෂකයෙකුට පමණක් ප්‍රචාරය දීම", "මැතිවරණ ප්‍රතිඵල වෙනස් කර ප්‍රකාශ කිරීම", "අපේක්ෂකයන් ගැන අසත්‍ය මඩ ප්‍රචාර ගෙන යාම", "මැතිවරණ කොමිසමේ මාධ්‍ය උපමාන අනුව රාජ්‍ය හා පෞද්ගලික මාධ්‍ය කටයුතු කළ යුතුය."),
    q("විදුලි සංදේශ නියාමන කොමිෂන් සභාව (TRCSL) ප්‍රධාන වශයෙන් නියාමනය කරන්නේ කුමන ක්ෂේත්‍රයද?", "දුරකථන සේවා, අන්තර්ජාල සැපයුම් හා ගුවන්විදුලි/රූපවාහිනී සංඛ්‍යාත වර්ණාවලිය", "පාසල් විභාග ප්‍රශ්න පත්‍ර", "පළාත් සභා අයවැය", "සමථ මණ්ඩල ගිවිසුම්", "සීමිත පොදු සම්පතක් වන සංඛ්‍යාත බලපත්‍ර කළමනාකරණය කිරීම TRCSL වගකීමකි."),
    q("ජනමාධ්‍ය මඟින් ස්වාභාවික ආපදා අවස්ථාවකදී ඉටු කළ යුතු ජීවිතාරක්ෂක කාර්යභාරය කුමක්ද?", "නිල ආපදා පූර්ව අනතුරු නිවේදන, ආරක්ෂිත ස්ථාන හා සහන අංක නිවැරදිව ප්‍රචාරය කිරීම", "කටකතා පතුරුවා මහජන කලබල ඇති කිරීම", "විපතට පත් පුද්ගලයන්ගේ අසරණ දර්ශන විකිණීම", "විකාශන කටයුතු නතර කිරීම", "කාලගුණ හා ආපදා මධ්‍යස්ථානයේ නිවැරදි තොරතුරු ඉක්මනින් ජනතාවට ලබාදීම ජීවිත රැසක් බේරා ගනී."),
    q("අන්තර්ජාලය හරහා පුද්ගලයෙකුට අපහාස කිරීම, තර්ජනය කිරීම හෝ අවසරයකින් තොරව පෞද්ගලික ඡායාරූප පළ කිරීම හඳුන්වන්නේ කුමන නමින්ද?", "සයිබර් හිංසනය (Cyberbullying / Online Harassment)", "පුරවැසි අධ්‍යාපනය", "සාමූහික කේවල් කිරීම", "ඩිජිටල් සාක්ෂරතාව", "2007 අංක 24 පරිගණක අපරාධ පනත හා සමාන්තර නීති යටතේ සයිබර් අපරාධවලට එරෙහිව පියවර ගත හැක."),
    q("සමාජ ජාල භාවිතයේදී තම පෞද්ගලික දත්ත හා ඡායාරූප ආරක්ෂා කර ගැනීමට පරිශීලකයා ගත යුතු මූලික පියවර කුමක්ද?", "ශක්තිමත් මුරපද භාවිතය, පෞද්ගලිකත්ව සැකසුම් (Privacy Settings) සකස් කිරීම හා නාඳුනන සබැඳි විවෘත නොකිරීම", "සියලු බැංකු රහස් අංක ප්‍රසිද්ධ කිරීම", "ඕනෑම අයෙකුට ගිණුම භාර දීම", "මුරපදය හැඳුනුම්පතේ ලිවීම", "ඩිජිටල් ආරක්ෂාව (Cyber Security) ගැන දැනුවත් වීම වර්තමාන පුරවැසියාට අත්‍යවශ්‍යය."),
    q("ශ්‍රී ලංකාවේ 'සංවර්ධන සන්නිවේදනය' (Development Communication) තුළ ජනමාධ්‍ය ඉටු කරන කාර්යය කුමක්ද?", "සෞඛ්‍ය, කෘෂිකර්මය, අධ්‍යාපනය හා පරිසර සංරක්ෂණය පිළිබඳව ප්‍රජාව දැනුවත් කර සංවර්ධනයට දායක කර ගැනීම", "ප්‍රචණ්ඩත්වය පමණක් ප්‍රචාරය කිරීම", "කෘෂිකර්මාන්තය විවේචනය කිරීම", "වෙළඳපොළ ඒකාධිකාර දිරිගැන්වීම", "අධ්‍යාපනික හා විද්‍යා වැඩසටහන් මඟින් සමාජයේ ධනාත්මක වෙනසක් ඇති කිරීම මෙහි අරමුණයි."),
    q("මාධ්‍ය නිදහස යන්නෙන් අදහස් වන්නේ මාධ්‍යයට ඕනෑම අසත්‍යයක් හෝ වෛරයක් ප්‍රචාරය කිරීමේ අසීමිත බලයක්ද?", "නැත, සත්‍යවාදී බව, පෞද්ගලිකත්වය, ජාතික සමගිය හා අධිකරණ ගෞරවය යන වගකීම්වලට යටත්ය", "ඔව්, කිසිදු නීතිමය සීමාවක් නැත", "ඔව්, වෛරී ප්‍රකාශ පළ කළ හැක", "ඔව්, ළමා අපරාධ වීඩියෝ පෙන්විය හැක", "නිදහස හා වගකීම එකම කාසියක දෙපැත්ත මෙන් එකට බැඳී පවතී."),
    q("පුවත්පතක හෝ වෙබ් අඩවියක පළ වූ 'වැරදි පුවතක්' නිසා කෙනෙකුගේ කීර්තිනාමයට හානි වූ විට ගත හැකි ආචාරධර්මීය හා නීතිමය පියවර මොනවාද?", "නිවැරදි කිරීමක් ඉල්ලීම, PCCSL වෙත පැමිණිලි කිරීම හෝ සිවිල් අපහාස නඩු පැවරීම", "මාධ්‍ය කාර්යාලයට ගල් ගැසීම", "මාධ්‍යවේදීන්ට තර්ජනය කිරීම", "සමථ මණ්ඩලය විසුරුවා හැරීම", "ශිෂ්ට සම්පන්න සමාජයක මාධ්‍ය ගැටලු විසඳන්නේ ආචාරධර්ම පැමිණිලි හා නීතිමය මාර්ගවලින් මිස ප්‍රචණ්ඩත්වයෙන් නොවේ."),
    q("රටේ පුරවැසියන්ගේ 'මහජන මතය' සාධාරණ ලෙස පාලකයන් වෙත දැනුම් දීමේ ප්‍රජාතන්ත්‍රවාදී ක්‍රම මොනවාද?", "සාමකාමී රැස්වීම්, පෙත්සම්, පුවත්පත් ලිපි, සිවිල් සංවාද සහ ඡන්දය ප්‍රකාශ කිරීම", "පොදු දේපළ ගිනි තැබීම", "පාසල් දරුවන්ට පහර දීම", "මාර්ග අවහිර කර ගිලන් රථ වැළැක්වීම", "ව්‍යවස්ථාවෙන් තහවුරු කළ සාමකාමී රැස්වීමේ හා අදහස් දැක්වීමේ අයිතිය යහපත් ප්‍රජාතන්ත්‍රවාදයක් පවත්වා ගනී."),
    q("වෙළඳ දැන්වීම්කරණයේදී 'පාරිභෝගික ආචාරධර්ම' කඩ වන අවස්ථාවක් වන්නේ කුමක්ද?", "සෞඛ්‍යයට අහිතකර නිෂ්පාදන හා දරුවන් නොමඟ යවන අසත්‍ය පොරොන්දු දැන්වීම්වලින් පෙන්වීම", "නිෂ්පාදනයේ සැබෑ මිල පැහැදිලිව දැක්වීම", "කල් ඉකුත් වන දිනය පෙන්වීම", "පාරිසරික අගය දැන්වීම", "ළමා මනස ඉලක්ක කරගත් අසත්‍ය වෙළඳ ප්‍රචාර සමාජ වගකීමෙන් යුතු මාධ්‍ය ප්‍රතික්ෂේප කළ යුතුය."),
    q("ශ්‍රී ලංකාවේ 'දුම්කොළ හා මද්‍යසාර පිළිබඳ ජාතික අධිකාරි පනත' (NATA) යටතේ ජනමාධ්‍යයට පනවා ඇති තහනම කුමක්ද?", "දුම්වැටි හා මත්පැන් ප්‍රචාරණය සඳහා සෘජු හෝ වක්‍ර දැන්වීම් හා අනුග්‍රහ පළ කිරීම තහනම් කිරීම", "සෞඛ්‍ය වැඩසටහන් තහනම් කිරීම", "ක්‍රීඩා පුවත් තහනම් කිරීම", "ළමා චිත්‍රපට තහනම් කිරීම", "මහජන සෞඛ්‍යය රැකීමට මාධ්‍ය හරහා මත්ද්‍රව්‍ය ප්‍රචාරණය නීතියෙන් සීමා කර ඇත."),
    q("ජනමාධ්‍ය මඟින් පාසල් සිසුන් සඳහා ගුණාත්මක දැනුම බෙදාදීමට ශ්‍රී ලංකාවේ ක්‍රියාත්මක ප්‍රධාන රාජ්‍ය සේවාවක් කුමක්ද?", "අධ්‍යාපනික රූපවාහිනී හා ගුවන්විදුලි නාලිකා (ඊ-තක්සලාව හා ගුරු ගෙදර වැනි)", "කහ පුවත්පත් නාලිකා", "වාණිජ වෙළඳ දැන්වීම් නාලිකා", "විදේශීය ක්‍රීඩා ඔට්ටු අඩවි", "නිදහස් අධ්‍යාපනයට සමාන්තරව දුරස්ථ අධ්‍යාපනය සැලසීමට ජනමාධ්‍ය මහත් සේ උපකාරී වේ."),
    q("මහජන මතය මැන බැලීමට 'ජනමත සමීක්ෂණ' (Opinion Polls) පවත්වන විට එහි විශ්වසනීයත්වය රඳා පවතින්නේ කුමක් මතද?", "නියැදියේ අපක්ෂපාතී බව, ප්‍රශ්නවල මධ්‍යස්ථ බව හා සියලු සමාජ ස්තර නියෝජනය වීම", "එක් කණ්ඩායමකින් පමණක් ප්‍රශ්න ඇසීම", "ප්‍රතිඵල හිතාමතා වෙනස් කිරීම", "කුඩා දරුවන්ගෙන් පමණක් ඇසීම", "විද්‍යාත්මක නියැදීමකින් තොරව පවත්වන සමාජ මාධ්‍ය ඡන්ද විමසීම් සැබෑ මහජන මතය නිරූපණය නොකරයි."),
    q("ප්‍රවෘත්ති වාර්තාකරණයේදී 'කරුණු සහ මත' (Facts vs Opinions) වෙන් කර හඳුනාගැනීම වැදගත් වන්නේ ඇයි?", "සත්‍ය සිදුවීම හා ලේඛකයාගේ පෞද්ගලික අදහස පටලවා නොගෙන නිවැරදි තීරණ ගැනීමට", "සියලු මත තහනම් කිරීමට", "පුවත්පත් මිල වැඩි කිරීමට", "සාක්ෂි නොසලකා හැරීමට", "'ඔප්පු කළ හැකි සිදුවීම' කරුණක් වන අතර 'පුද්ගල විනිශ්චය' මතයක් බව පාඨකයා දැන සිටිය යුතුය."),
    q("මුද්‍රිත පුවත්පත් වලට වඩා 'ගුවන්විදුලිය' ග්‍රාමීය හා ආපදා කාලීන සන්නිවේදනයේදී අදටත් ප්‍රබල වන්නේ ඇයි?", "විදුලිය විසන්ධි වූ විට පවා බැටරි මගින් ක්‍රියා කළ හැකි වීම හා වැඩ කරන ගමන් සවන් දිය හැකි වීම", "එහි රූප පෙන්වන බැවිනි", "අන්තර්ජාලය අනිවාර්ය බැවිනි", "කියවීම අත්‍යවශ්‍ය බැවිනි", "හදිසි ආපදා හා ගමනාගමනයේදී ගුවන්විදුලිය වේගවත් හා ලාභදායී මාධ්‍යයකි."),
    q("මාධ්‍ය ආයතනවල 'වාරණය' (Censorship) යනු කුමක්ද?", "ප්‍රකාශන පළ කිරීමට හෝ විකාශනය කිරීමට පෙර රජය හෝ අධිකාරිය විසින් ඒවා පරීක්ෂා කර කපා හැරීම හෝ තහනම් කිරීම", "නව පුවත්පත්වලට මුද්‍රණ කඩදාසි දීම", "මාධ්‍යවේදීන්ට උසස්වීම් දීම", "පුස්තකාල ඉදිකිරීම", "ප්‍රජාතන්ත්‍රවාදී රටක ජාතික ආරක්ෂාව වැනි අතිශය සීමිත හේතු මත මිස රාජ්‍ය වාරණය නොපැනවිය යුතුය."),
    q("ශ්‍රී ලංකාවේ 'මාධ්‍යවේදීන්ගේ ආරක්ෂාව හා ස්වාධීනත්වය' රැකීම වැදගත් වන්නේ කුමන ජාතික අරමුණක් උදෙසාද?", "දූෂණ හෙළි කර යහපාලනය තහවුරු කිරීම හා පුරවැසියන්ට සත්‍ය තොරතුරු ලබාදීම", "ව්‍යාපාරිකයන්ගේ පෞද්ගලික වාසි රැකීමට", "අධිකරණ නියෝග කඩ කිරීමට", "මැතිවරණ කල් දැමීමට", "මාධ්‍යවේදීන්ට බියෙන් තොරව සත්‍ය වාර්තා කිරීමට ඇති පරිසරය නිදහස් සමාජයක මිනුම් දණ්ඩකි."),
    q("අන්තර්ජාලයේ 'ප්‍රකාශන හිමිකම' (Copyright) හා 'බුද්ධිමය දේපළ අයිතිය' ආරක්ෂා කිරීම වැදගත් වන්නේ ඇයි?", "අනෙකාගේ ලිපි, ගීත, ඡායාරූප හා පර්යේෂණ හොරකම් කිරීම වැළැක්වී නිර්මාණකරුවන් දිරිමත් වන බැවිනි", "සියලු පොත්පත් පිළිස්සීමට", "ගීත ගායනය තහනම් කිරීමට", "පාසල් අධ්‍යාපනය නතර කිරීමට", "මූලාශ්‍රය සඳහන් නොකර අන් අයගේ නිර්මාණ උපුටා ගැනීම (Plagiarism) සදාචාර හා නීති විරෝධී වේ."),
    q("විවිධ භාෂාවලින් ප්‍රවෘත්ති හා විශේෂාංග පළ කරන මාධ්‍ය ආයතන ජාතික සමගියට දායක වන්නේ කෙසේද?", "සිංහල, දෙමළ හා ඉංග්‍රීසි පාඨකයන්ට එකම ජාතික යථාර්ථය සමබරව හා ගෞරවයෙන් සන්නිවේදනය කිරීමෙන්", "එක් ප්‍රජාවකට පමණක් පුවත් සීමා කිරීමෙන්", "වෛරී භාෂාව භාවිත කිරීමෙන්", "පරිවර්තන නතර කිරීමෙන්", "භාෂා අතර පාලමක් ලෙස ක්‍රියා කරන මාධ්‍ය ජන කොටස් අතර සැකය දුරු කරයි."),
    q("පුවත්පතක හෝ රූපවාහිනියක පළ වන 'වෙළඳ දැන්වීමක්' හා 'ප්‍රවෘත්ති වාර්තාවක්' අතර ඇති පැහැදිලි වෙනස පාඨකයා දැන සිටිය යුත්තේ ඇයි?", "මුදල් ගෙවා ප්‍රචාරය කරන දැන්වීම් හා ස්වාධීන මාධ්‍ය වාර්තා වෙන් කර හඳුනාගැනීමට", "දැන්වීම් සියල්ල නීති පනත් ලෙස සැලකීමට", "පුවත්පත මිලදී නොගෙන සිටීමට", "විදුලි පහන් නිවා දැමීමට", "මුදල් ගෙවා ප්‍රචාරය කරන අන්තර්ගතයන් (Sponsored Content) සැබෑ ප්‍රවෘත්ති ලෙස වරදවා වටහා නොගත යුතුය."),
    q("නව මාධ්‍ය භාවිතයේදී 'ඩිජිටල් පියසටහන' (Digital Footprint) පිළිබඳව සිසුන් හා පුරවැසියන් සැලකිලිමත් විය යුත්තේ ඇයි?", "අන්තර්ජාලයේ පළ කරන ඕනෑම අදහසක් හෝ ඡායාරූපයක් දිගු කලක් පැවත අනාගත රැකියා හා කීර්තිනාමයට බලපාන බැවිනි", "අන්තර්ජාලයෙන් කිසිවක් මතක නොතබන බැවිනි", "පාවහන් ප්‍රමාණය මැනීමට", "පාසල් විභාග අවලංගු වීමට", "සමාජ මාධ්‍ය තුළ ආචාරශීලීව හා වගකීමෙන් අදහස් පළ කිරීම ඩිජිටල් පුරවැසිභාවයේ මූලිකාංගයකි."),
    q("මහජන සේවා ගුවන්විදුලිය හා රූපවාහිනිය (Public Service Media) සතු විශේෂ සමාජ වගකීම කුමක්ද?", "වාණිජ ලාභයට පමණක් යට නොවී අධ්‍යාපනික, සංස්කෘතික හා සුළුතර ප්‍රජාවන්ගේ වැඩසටහන්ද විකාශනය කිරීම", "වෙළඳ දැන්වීම් පමණක් පෙන්වීම", "රාජ්‍ය පක්ෂ ප්‍රචාරණය පමණක් කිරීම", "ප්‍රවෘත්ති විකාශන නැවැත්වීම", "බී.බී.සී. වැනි සැබෑ මහජන සේවා මාධ්‍ය මහජන අරමුදලින් පොදු යහපත උදෙසා අපක්ෂපාතීව සේවය කරයි."),
    q("මාධ්‍ය වාර්තාකරණයේදී 'අධිකරණයට අපහාස කිරීම' (Contempt of Court) වළක්වා ගැනීමට මාධ්‍යවේදීන් ප්‍රවේශම් වන්නේ ඇයි?", "විභාග වෙමින් පවතින නඩුවක විනිශ්චයට බලපෑම් නොකර සාධාරණ නඩු විභාගයක් රැකීමට", "විනිසුරුවරුන්ගේ නම් සැඟවීමට", "පොලිස් වාර්තා විකිණීමට", "අධිකරණ වසා දැමීමට", "නඩුවක් අවසන් වීමට පෙර සැකකරුවෙකු වැරදිකරු යැයි මාධ්‍ය මඟින් තීන්දු කිරීම (Media Trial) සුදුසු නැත."),
    q("ජනමාධ්‍ය හරහා සමාජයට 'ආකල්පමය වෙනසක්' ගෙන ආ හැකි ධනාත්මක ක්ෂේත්‍ර මොනවාද?", "මාර්ග ආරක්ෂාව, ඩෙංගු මර්දනය, පරිසර සංරක්ෂණය, අල්ලස් විරෝධය හා භාෂා සංහිඳියාව", "මත්ද්‍රව්‍ය ප්‍රචාරණය", "ජාතිවාදී වෛරය", "ළමා හිංසනය", "නිර්මාණාත්මක නාට්‍ය, ගීත හා වාර්තා වැඩසටහන් සමාජයේ යහපත් වටිනාකම් පෝෂණය කරයි."),
    q("දේශපාලන නායකයන් හා මහජනතාව අතර 'ද්වි-මාර්ගික සන්නිවේදන පාලමක්' ලෙස ජනමාධ්‍ය ක්‍රියා කරන්නේ කෙසේද?", "රජයේ ප්‍රතිපත්ති ජනතාවට පැහැදිලි කරන අතරම ජනතාවගේ දුක්ගැනවිලි හා විවේචන පාලකයන් වෙත ගෙන යාමෙන්", "පාලකයන්ගේ පැසසුම් පමණක් ගැයීමෙන්", "මහජන පැමිණිලි කසළ කූඩයට දැමීමෙන්", "පාර්ලිමේන්තු විවාද වසා දැමීමෙන්", "වගකිවයුතු ජනමාධ්‍යයක් පාලකයන් හා පාලිතයන් අතර නිරන්තර සංවාදයක් පවත්වාගනී."),
    q("පුවත්පතක හෝ වෙබ් අඩවියක ප්‍රකාශයට පත් වන දත්ත මූලාශ්‍රවල 'පක්ෂග්‍රාහීත්වය' (Media Bias) හඳුනා ගන්නේ කෙසේද?", "වාර්තාව යොදාගන්නා ආවේගශීලී වචන, මගහැර ඇති විරුද්ධ අදහස් හා අනුග්‍රාහකයන් කවුදැයි විමසීමෙන්", "අකුරුවල වර්ණය බැලීමෙන් පමණි", "පිටු අංකය බැලීමෙන්", "මුද්‍රණාලයේ ලිපිනයෙන්", "විවිධ මාධ්‍ය ආයතනවල වාර්තා සංසන්දනය කර කියවීමෙන් සත්‍යයට වඩාත් සමීප විය හැක."),
    q("ශ්‍රී ලංකාවේ මුද්‍රිත හා විද්‍යුත් මාධ්‍යවල භාවිත කළ යුතු 'භාෂා ශෛලිය' පිළිබඳව සැලකිලිමත් විය යුත්තේ ඇයි?", "මහජනතාවගේ භාෂා රීති රැකීමට හා අසභ්‍ය හෝ අවමන්සහගත වචන සමාජගත වීම වැළැක්වීමට", "සෑම වචනයක්ම ඉංග්‍රීසියෙන් ලිවීමට", "ව්‍යාකරණ සම්පූර්ණයෙන් ඉවත් කිරීමට", "ළමුන්ට තේරුම් ගත නොහැකි ලෙස ලිවීමට", "මාධ්‍ය යනු ජනතාවගේ භාෂා ගුරුවරයෙකු බඳු වන බැවින් නිවැරදි හා ශිෂ්ට භාෂාවක් භාවිත කළ යුතුය."),
    q("තොරතුරු තාක්ෂණ යුගයේදී 'ඩිජිටල් බෙදීම' (Digital Divide) අඩු කිරීම වැදගත් වන්නේ ඇයි?", "ග්‍රාමීය හා දිළිඳු ප්‍රජාවන්ටද අන්තර්ජාලය, ඊ-අධ්‍යාපනය හා තොරතුරු අවස්ථා සමානව ලැබිය යුතු බැවිනි", "නගරවල අන්තර්ජාලය විසන්ධි කිරීමට", "සියලු පරිගණක තහනම් කිරීමට", "තැපැල් සේවාව වැසීමට", "තොරතුරු ප්‍රවේශයේ සමානාත්මතාව වත්මන් සමාජ සාධාරණත්වයේ අනිවාර්ය කොටසකි."),
    q("අන්තර්ජාලය හරහා පැතිරෙන 'ක්ලික්බේට්' (Clickbait - ආකර්ෂණීය ව්‍යාජ ශීර්ෂපාඨ) මඟින් සිදුවන හානිය කුමක්ද?", "ප්‍රචාරණ ආදායම් ලබාගැනීමට පාඨකයන් රවටා පුවත් පිළිබඳ මහජන විශ්වාසය බිඳ දැමීම", "විද්‍යාත්මක දැනුම දියුණු කිරීම", "මාධ්‍ය ආචාරධර්ම ශක්තිමත් කිරීම", "විභාග සමත් වීම", "සිරස්තලය හා අන්තර්ගතය අතර ගැළපීමක් නොමැති ක්ලික්බේට් වෙබ් අඩවි මාධ්‍ය විශ්වසනීයත්වය පිරිහෙළයි."),
    q("පුවත්පත් නිදහස හා මාධ්‍ය වගවීම සුරැකීම සඳහා 'කතුවරුන්ගේ සංසදය' (Editors' Guild) විසින් සම්පාදිත ආචාරධර්ම සංග්‍රහයේ ප්‍රධාන කරුණක් කුමක්ද?", "සත්‍යයට ගරු කිරීම, පෞද්ගලිකත්වය රැකීම, පිළිතුරු දීමේ අයිතිය හා සියදිවි නසාගැනීම් වගකීමෙන් වාර්තා කිරීම", "අල්ලස් ලබාගෙන ප්‍රවෘත්ති ලිවීම", "ළමුන්ගේ ඡායාරූප අවසර නැතිව පළ කිරීම", "විරුද්ධ පක්ෂවලට අපහාස කිරීම", "සියදිවි නසාගැනීම් විස්තරාත්මකව වාර්තා නොකිරීම ඇතුළු සංවේදී මාධ්‍ය ආචාරධර්ම මෙහි අඩංගුය."),
    q("රූපවාහිනී වැඩසටහන් නැරඹීමේදී දරුවන් ආරක්ෂා කිරීමට යොදාගන්නා 'වයස් වර්ගීකරණ සංකේත' (Parental Guidance / Age Ratings) මඟින් කෙරෙන්නේ කුමක්ද?", "ප්‍රචණ්ඩත්වය හෝ වැඩිහිටි අන්තර්ගතයන්ගෙන් ළමා මනස ආරක්ෂා කිරීමට දෙමාපියන්ට මග පෙන්වීම", "සියලු කාටූන් තහනම් කිරීම", "රූපවාහිනී බලපත්‍ර අවලංගු කිරීම", "ළමුන්ට පාසල් නිවාඩු දීම", "මාධ්‍ය අන්තර්ගතයන් වයසට ගැළපෙන පරිදි තෝරා දීමට වැඩිහිටියන් දැනුවත් විය යුතුය."),
    q("මහජන මතයක් 'තර්කානුකූල හා පරිණත' වන්නේ කුමන සමාජ පරිසරයකදීද?", "විවෘත විවාද, නිදහස් පුස්තකාල, විවිධ අදහස්වලට ඇහුම්කන් දීම හා ගුණාත්මක අධ්‍යාපනය පවතින විට", "එක් රූපවාහිනී නාලිකාවක් පමණක් පවතින විට", "විරුද්ධ මත තහනම් කළ විට", "කටකතා පමණක් විශ්වාස කරන විට", "බහුවිධ තොරතුරු ප්‍රභවයන් හා නිදහස් චින්තනය සෞඛ්‍ය සම්පන්න මහජන මතයක අත්තිවාරමයි."),
    q("වර්තමානයේ පුද්ගලයෙකු 'ඩිජිටල් සාක්ෂරතාවයෙන් හෙබි සක්‍රීය පුරවැසියෙකු' විය යුත්තේ ඇයි?", "මාර්ගගත රාජ්‍ය සේවා ලබාගැනීමට, ව්‍යාජ පුවත් හඳුනාගැනීමට හා ආරක්ෂිතව අදහස් ප්‍රකාශ කිරීමට", "සෑම කටකතාවක්ම Share කිරීමට", "අන්තර්ජාලයෙන් මුදල් වංචා කිරීමට", "පාසල් අධ්‍යාපනය අත්හැරීමට", "21 වන සියවසේ පුරවැසි කුසලතා අතර ඩිජිටල් හා මාධ්‍ය සාක්ෂරතාව ප්‍රමුඛ වේ."),
    q("රටේ සංස්කෘතික උරුමයන් හා කලා නිර්මාණ රැකගැනීමේදී 'සාම්ප්‍රදායික ජන සන්නිවේදන මාධ්‍ය' (කවි කොළ, කෝලම්, සොකරි, තොරණ) වැදගත් වන්නේ ඇයි?", "සමාජ වටිනාකම්, සදාචාරය හා ජන විඥානය පරම්පරාවෙන් පරම්පරාවට සජීවීව ගෙන යන බැවිනි", "ඒවා නූතන කෘත්‍රිම බුද්ධියට අයත් නිසා", "අන්තර්ජාලයෙන් පමණක් ක්‍රියාත්මක නිසා", "විදේශීය වෙළඳ නීති පවතින නිසා", "ගැමි කලා හා ජනශ්‍රැති ප්‍රජා සමගිය හා සංස්කෘතික අනන්‍යතාව ශක්තිමත් කරයි."),
    q("පුවත්පතක හෝ ප්‍රවෘත්ති වෙබ් අඩවියක පළවන 'විශේෂාංග ලිපියක්' (Feature Article) සාමාන්‍ය ප්‍රවෘත්තියකින් වෙනස් වන්නේ කෙසේද?", "විශේෂාංග ලිපිය සිදුවීමේ පසුබිම, මානුෂීය කතාව හා ගැඹුරු විශ්ලේෂණය සවිස්තරව ඉදිරිපත් කරයි", "විශේෂාංග ලිපිය වාක්‍ය දෙකකට සීමා වේ", "විශේෂාංග ලිපියේ කරුණු අසත්‍ය විය යුතුය", "එය දැන්වීම් පිටුවේ පමණක් පළ වේ", "ප්‍රවෘත්තියක් ක්ෂණිකව 'කුමක් සිදුවීද' යන්න කියන අතර විශේෂාංගය 'ඇයි සහ කෙසේ සිදුවීද' යන්න විමසයි."),
    q("රාජ්‍ය හෝ පෞද්ගලික මාධ්‍යවේදීන් 'මූලාශ්‍රවල රහස්‍යභාවය' (Confidentiality of Sources) ආරක්ෂා කරන්නේ ඇයි?", "රාජ්‍ය දූෂණ හෙළි කරන තොරතුරු සපයන්නන්ගේ ජීවිත හා රැකියා ආරක්ෂා කිරීම සඳහා", "වැරදි පුවත් සඟවා ගැනීමට", "අල්ලස් ගැනීමට", "පුවත්පත් විකිණීම නැවැත්වීමට", "තොරතුරු ලබාදෙන්නන්ගේ අනන්‍යතාව රැකීම ගවේෂණාත්මක පත්‍රකලාවේදයේ විශ්වාසය පවත්වාගනී."),
    q("මහජනතාව අතර 'පුවත්පත් කියවීමේ හා විමසිලිමත් වීමේ පුරුද්ද' වර්ධනය කිරීමෙන් ප්‍රජාතන්ත්‍රවාදයට ලැබෙන ප්‍රතිලාභය කුමක්ද?", "පාලකයන්ගේ ප්‍රතිපත්ති විවේචනාත්මකව තක්සේරු කර බුද්ධිමත්ව ඡන්දය භාවිත කළ හැකි පුරවැසියන් බිහිවීම", "කටකතා පමණක් විශ්වාස කිරීම", "සියලු මැතිවරණ වර්ජනය කිරීම", "පුස්තකාල වසා දැමීම", "තොරතුරුවලින් සන්නද්ධ වූ පුරවැසි සමාජයක් ඕනෑම ප්‍රජාතන්ත්‍රවාදයක ශක්තිමත්ම ආරක්ෂාවයි."),
    q("ප්‍රවෘත්ති කතුවරුන් විසින් ප්‍රවෘත්තියක් ප්‍රකාශයට පත් කිරීමේදී අනුගමනය කරන '5Ws and 1H' නීතිය මඟින් විමසන්නේ කුමක්ද?", "කවුද (Who), කුමක්ද (What), කවදාද (When), කොහේද (Where), ඇයි (Why) සහ කෙසේද (How)", "වෙළඳ ලාභය පමණක්", "දේශපාලන පක්ෂයේ කැමැත්ත පමණි", "රේගු බදු හා වරිපනම්", "නිවැරදි හා සම්පූර්ණ ප්‍රවෘත්ති වාර්තාවක් සඳහා මෙම මූලික ප්‍රශ්න හයට පිළිතුරු තිබිය යුතුය."),
    q("ප්‍රවෘත්ති සාකච්ඡාවකදී හෝ විවාදයකදී 'සාක්ෂි නොමැති පෞද්ගලික අපහාස' ප්‍රචාරය කිරීම වැරදි වන්නේ ඇයි?", "පුද්ගල ගෞරවය හා කීර්තිනාමය විනාශ වී ප්‍රකාශන නිදහස අවභාවිත වන බැවිනි", "වැඩසටහන කෙටි වන නිසා", "කැමරා ක්‍රියා නොකරන නිසා", "දැන්වීම් අඩු වන නිසා", "වගකිවයුතු මාධ්‍ය විවේචන එල්ල කරන්නේ ප්‍රතිපත්ති හා ක්‍රියාකලාපයට මිස පෞද්ගලික අපහාසවලට නොවේ."),
    q("නව මාධ්‍ය හරහා 'සමාජ යහපත උදෙසා මහජන මතයක්' ගොඩනැගිය හැකි ධනාත්මක අවස්ථාවක් කුමක්ද?", "රුධිර දාන කඳවුරු, ආපදා ආධාර රැස් කිරීම, රුක් රෝපණය හා පාරිසරික අසාධාරණ පෙන්වා දීම", "වෛරී කටකතා පැතිරවීම", "පුද්ගලික දුරකථන අංක හෙළි කිරීම", "විභාග ප්‍රශ්න පත්‍ර ව්‍යාජ ලෙස විකිණීම", "ඩිජිටල් සමාජ ජාල යහපත් ප්‍රජා සත්කාර හා සිවිල් බලමුළු ගැන්වීම් සඳහා ප්‍රබල මෙවලමකි."),
    q("ශ්‍රී ලංකාවේ විද්‍යුත් මාධ්‍ය ආයතනයක් පවත්වාගෙන යාමේදී මහජන යහපත උදෙසා පනවා ඇති මූලික කොන්දේසිය කුමක්ද?", "ජාතික ආරක්ෂාව, ආගමික සංහිඳියාව, ළමා ආරක්ෂාව හා සමාජ සදාචාරයට හානි නොකිරීම", "රාජ්‍ය බදු නොගෙවා සිටීම", "පුවත් විකාශනය නැවැත්වීම", "දේශීය කලා නිර්මාණ තහනම් කිරීම", "පොදු ගුවන් තරංග භාවිත කරන සෑම නාලිකාවක්ම මහජන වගකීමෙන් ක්‍රියා කළ යුතුය."),
    q("රටේ පාසල් තුළ 'මාධ්‍ය සංගම් හා විවාද කණ්ඩායම්' පවත්වාගෙන යාමෙන් සිසුන් තුළ ගොඩනැගෙන ප්‍රධාන පුරවැසි කුසලතා මොනවාද?", "නිවැරදි සන්නිවේදනය, තොරතුරු විමසීම, අනෙක් මත ඉවසීම හා නායකත්වය", "ආත්මාර්ථකාමී බව", "වෛරී ප්‍රකාශ පුරුදු වීම", "කියවීම නතර කිරීම", "විධිමත් සන්නිවේදන කුසලතා පාසල් අවධියේ සිටම ප්‍රජාතන්ත්‍රවාදී සංස්කෘතිය පෝෂණය කරයි."),
    q("මාධ්‍ය හරහා 'සංස්කෘතික ආක්‍රමණයක්' හෝ පාරිභෝගිකවාදී අන්ධ අනුකරණයක් සිදුවන විට පුරවැසියා ක්‍රියා කළ යුත්තේ කෙසේද?", "විචාර බුද්ධියෙන් යුතුව දේශීය හා විශ්වීය සංස්කෘතීන්හි හොඳ දේ පමණක් තෝරා ගැනීම", "සියලු අධ්‍යාපන වැඩසටහන් නැවැත්වීම", "තම මව්භාෂාව අමතක කිරීම", "වෙළඳ දැන්වීම් දුටු සියල්ල ණයට ගැනීම", "සංස්කෘතික විවෘතභාවය සමඟ තම අනන්‍යතාව රැකගැනීම බුද්ධිමත් මාධ්‍ය භාවිතයයි."),
    q("ජනමාධ්‍යය, මහජන මතය හා සිවිල් සමාජය එක්ව ක්‍රියා කිරීමෙන් ප්‍රජාතන්ත්‍රවාදී රාජ්‍යයකට අත්වන ශ්‍රේෂ්ඨතම ප්‍රතිඵලය කුමක්ද?", "පාලකයන් ජනතාවට වගකියන, විනිවිදභාවයෙන් යුත් ජීවමාන ප්‍රජාතන්ත්‍රවාදයක් පවත්වාගැනීම", "සියලු මැතිවරණ අහෝසි වීම", "ඒකාධිපති පාලනයක් ඇති වීම", "තොරතුරු දැනගැනීමේ පනත අවලංගු වීම", "පුරවැසි අයිතීන් ආරක්ෂා කරන සක්‍රීය මුරකරුවන් ලෙස මාධ්‍ය හා සිවිල් සමාජය කටයුතු කරයි."),
    q("මහජන මතයක් ගොඩනැගීමේදී පවුල, පාසල, ආගමික ස්ථාන හා සම වයස් කණ්ඩායම් හඳුන්වන්නේ කුමන ආයතන ලෙසද?", "ප්‍රාථමික සමාජානුයෝජන හා මහජන මත ගොඩනැගීමේ නියෝජිතයන්", "පළාත් පාලන ආයතන", "අධිකරණ ආයතන", "රේගු ආයතන", "පුද්ගලයෙකුගේ දේශපාලන හා සමාජ ආකල්ප හැඩගැස්වීමට පවුල හා පාසල මූලික අඩිතාලම දමයි."),
    q("ශ්‍රී ලංකාවේ ජාතික ගුවන්විදුලි සේවාව 'ලංකා ගුවන්විදුලි සේවය' ලෙස ආරම්භ වී ආසියාවේ පැරණිතම ගුවන්විදුලි සේවාවක් වූයේ කුමන වර්ෂයේදීද?", "1925 (නිල විකාශනය දෙසැම්බර් 16)", "1948", "1972", "1982", "දකුණු ආසියාවේ පළමු ගුවන්විදුලි සේවය ලෙස 1925 දී කොළඹින් ගුවන්විදුලි විකාශනය ඇරඹිණි."),
    q("ශ්‍රී ලංකාවේ රූපවාහිනී විකාශන සේවා ආරම්භ කළ ප්‍රථම නාලිකාව වන ස්වාධීන රූපවාහිනී සේවය (ITN) හා රූපවාහිනී සංස්ථාව බිහිවූයේ කවදාද?", "1979 (ITN) සහ 1982 (ජාතික රූපවාහිනිය)", "1948 සහ 1956", "1960 සහ 1970", "1995 සහ 2000", "රූපවාහිනිය පැමිණීමත් සමඟ ශ්‍රව්‍ය දෘශ්‍ය සන්නිවේදනය රට පුරාම වේගයෙන් ව්‍යාප්ත විය."),
    q("ප්‍රවෘත්තියක් ඉදිරිපත් කිරීමේදී 'උඩු යටිකුරු පිරමීඩ ශෛලිය' (Inverted Pyramid Style) භාවිත කරන්නේ ඇයි?", "වඩාත්ම වැදගත් තොරතුරු ලිපියේ මුලින්ම දක්වා පාඨකයාට ක්ෂණික අවබෝධයක් ලබාදීමට", "වැදගත්ම කරුණ අවසාන වාක්‍යයේ සැඟවීමට", "කිසිදු තොරතුරක් නොලියා සිටීමට", "වෙළඳ දැන්වීම් පමණක් පළ කිරීමට", "කාලය සීමිත පාඨකයන්ට පළමු ඡේදයෙන්ම සිදුවීමේ හරය ග්‍රහණය කර ගැනීමට මෙය උපකාරී වේ."),
    q("මාධ්‍ය හරහා සමාජයට ඉදිරිපත් කරන 'දේශපාලන කාටූන්' (Political Cartoons) මඟින් ඉටු කරන විශේෂ කාර්යය කුමක්ද?", "රාජ්‍ය පාලනයේ දුර්වලතා හා සමාජ අසාධාරණ උපහාසාත්මක හා කලාත්මක ලෙස විවේචනය කිරීම", "පාසල් විෂය නිර්දේශය තහනම් කිරීම", "රේගු බදු ගණනය කිරීම", "මැතිවරණ පෝරම මුද්‍රණය කිරීම", "කෙටි චිත්‍රයකින් හා වචන කිහිපයකින් ගැඹුරු දේශපාලන පණිවිඩයක් සාමාන්‍ය ජනතාවට සන්නිවේදනය කරයි."),
    q("පුවත්පතක හෝ රූපවාහිනියක පළවන 'විද්‍යාත්මක සාක්ෂරතා වැඩසටහන්' (Science & Health Communication) ජනතාවට ප්‍රයෝජනවත් වන්නේ කෙසේද?", "මිථ්‍යා විශ්වාස දුරු කර වසංගත, පෝෂණය හා පාරිසරික ආරක්ෂාව ගැන නිවැරදි දැනුම දීමෙන්", "මිථ්‍යා මත ප්‍රචාරය කිරීමෙන්", "වෛද්‍ය ප්‍රතිකාර තහනම් කිරීමෙන්", "විද්‍යාවට අපහාස කිරීමෙන්", "COVID-19 වැනි වසංගත හා ඩෙංගු පාලනයේදී වෛද්‍ය උපදෙස් ජනගත කිරීමට මාධ්‍ය ප්‍රබල මෙහෙයක් ඉටු කරයි."),
    q("සමාජ මාධ්‍ය භාවිතයේදී 'කරුණු සොරකම් කිරීම හා අනවසරයෙන් පුද්ගලික ගිණුම්වලට පිවිසීම' (Hacking / Phishing) සම්බන්ධ නීතිය කුමක්ද?", "2007 අංක 24 දරන පරිගණක අපරාධ පනත (Computer Crimes Act)", "1987 ප්‍රාදේශීය සභා පනත", "1988 සමථ මණ්ඩල පනත", "1954 සාප්පු හා කාර්යාල පනත", "පරිගණක පද්ධතිවලට අනවසරයෙන් ඇතුළු වීම හා දත්ත විනාශ කිරීම මෙම පනතින් බරපතළ අපරාධයකි."),
    q("අන්තර්ජාලය හරහා වෛරී ප්‍රකාශ හා වාර්ගික නොසන්සුන්තා පතුරුවන පුද්ගලයෙකුට මුහුණ දීමට සිදුවන නීතිමය ප්‍රතිඵලය කුමක්ද?", "සිවිල් හා දේශපාලන අයිතිවාසිකම් සම්මුති පනත (ICCPR) හා දණ්ඩ නීති සංග්‍රහය යටතේ අත්අඩංගුවට ගෙන නඩු පැවරීම", "රජයෙන් මුදල් ත්‍යාග හිමිවීම", "වෘත්තීය සමිති තනතුරක් ලැබීම", "විදේශ ශිෂ්‍යත්වයක් හිමිවීම", "ප්‍රකාශන නිදහස අන් අයගේ ආරක්ෂාව හා ජාතික සාමය බිඳ දැමීමට යොදාගත නොහැක."),
    q("පුවත්පතක 'පාඨක ලිපි' (Letters to the Editor) තීරුව ප්‍රජාතන්ත්‍රවාදයට වැදගත් වන්නේ ඇයි?", "සාමාන්‍ය පුරවැසියන්ට තම ප්‍රදේශයේ ප්‍රශ්න හා පොදු අදහස් බලධාරීන්ගේ අවධානයට යොමු කිරීමට ඉඩ සලසන බැවිනි", "කතුවරයාගේ ඡායාරූප පමණක් පළ කිරීමට", "වෙළඳසැල් ලිපිනයන් මැකීමට", "රජයේ ගැසට් පත්‍රය අහෝසි කිරීමට", "පුරවැසියන්ගේ සෘජු හඬ ජනමාධ්‍ය තුළින් ඉස්මතු වීම මහජන සහභාගිත්වය ශක්තිමත් කරයි."),
    q("ජනමාධ්‍යවේදියෙකු ප්‍රවෘත්තියක් ලිවීමේදී 'මූලාශ්‍ර දෙකකින්වත් තහවුරු කිරීම' (Verification / Cross-checking) අනුගමනය කරන්නේ ඇයි?", "අසත්‍ය හා පක්ෂග්‍රාහී තොරතුරක් පළ වී මහජනතාව නොමඟ යාම වැළැක්වීමට", "පුවත ප්‍රමාද කර කල් දැමීමට", "වැඩි කඩදාසි නාස්ති කිරීමට", "පාඨකයන් අඩු කිරීමට", "විශ්වසනීයත්වය ජනමාධ්‍ය ආයතනයක සතු වටිනාම ප්‍රාග්ධනය වේ."),
    q("මාධ්‍ය හිමිකාරිත්වය රටේ ධනවත් ව්‍යාපාරිකයන් හෝ පාලකයන් කිහිප දෙනෙකු අත පමණක් ඒකරාශී වීමෙන් (Media Monopoly) ඇතිවන අනතුර කුමක්ද?", "මහජන මතය තනි පැත්තකට මෙහෙයවා විකල්ප හා ස්වාධීන හඬවල් යටපත් වීම", "සියලු ප්‍රවෘත්ති නොමිලේ සැමට ලැබීම", "මාධ්‍ය විවිධත්වය උපරිම වීම", "සියලු පුස්තකාල වැඩි දියුණු වීම", "විවිධත්වයෙන් යුත් මාධ්‍ය ආයතන (Media Pluralism) ප්‍රජාතන්ත්‍රවාදී විවෘත සමාජයකට අත්‍යවශ්‍යය."),
    q("දේශගුණික විපර්යාස, ඩිජිටල් ආරක්ෂාව හා මානව හිමිකම් ගැන තරුණ පරපුර අතර 'මහජන මතයක්' ගොඩනැගීමට වඩාත් ඵලදායී මාධ්‍ය කුමක්ද?", "සමාජ මාධ්‍ය, පොඩ්කාස්ට්, අන්තර්ක්‍රියාකාරී වෙබ් අඩවි හා පාසල් සංවාද වැඩසටහන්", "ටෙලිග්‍රෑම් පණිවිඩ පමණක්", "කළු ගල් ලිපි", "මුද්‍රිත ගැසට් පත්‍ර පමණක්", "තරුණ ප්‍රජාව බහුලව සම්බන්ධ වන ඩිජිටල් වේදිකා හරහා ධනාත්මක සමාජ දැනුවත් කිරීම් සාර්ථකව කළ හැක."),
    q("සමාජ මාධ්‍ය හරහා භාණ්ඩ ඇණවුම් කිරීමේදී හෝ මුදල් ගනුදෙනු කිරීමේදී 'ඩිජිටල් මූල්‍ය වංචාවලින්' (Phishing/Scams) ආරක්ෂා වන්නේ කෙසේද?", "බැංකු OTP අංක හා රහස් පද කිසිවෙකුට නොදීම හා නිල වෙබ් අඩවි පමණක් භාවිත කිරීම", "ලැබෙන සෑම OTP අංකයක්ම නාඳුනන අයට දීම", "සියලු බැංකු කාඩ් ඡායාරූප ෆේස්බුක් දැමීම", "නාඳුනන ත්‍යාග සබැඳිවලට මුදල් දැමීම", "ශ්‍රී ලංකා CERT (SLCERT) ආයතනය සයිබර් ආරක්ෂණ දැනුවත් කිරීම් හා පැමිණිලි භාරගැනීම සිදු කරයි."),
    q("රටේ පාසල් දරුවන් තුළ 'මාධ්‍ය සාක්ෂරතාව' කුඩා කල සිටම වර්ධනය කිරීම වැදගත් වන්නේ ඇයි?", "ප්‍රචාරක උපක්‍රම හා ව්‍යාජ තොරතුරුවලට නොරැවටී බුද්ධිමත්ව මාධ්‍ය පරිභෝජනය කිරීමට", "රූපවාහිනිය සම්පූර්ණයෙන් කඩා දැමීමට", "කිසිදු පොතක් නොකියවීමට", "සමාජ මාධ්‍ය ගිණුම් සිය ගණනක් සෑදීමට", "නිර්මාණශීලී හා විවේචනාත්මක පුරවැසියන් බිහි කිරීමට මාධ්‍ය සාක්ෂරතාව අධ්‍යාපනයට එක් කළ යුතුය."),
    q("ප්‍රජාතන්ත්‍රවාදී රටක 'ජනමාධ්‍යයෙන් සිදුවන ප්‍රධාන කාර්යභාර හතර' නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "තොරතුරු සැපයීම, අධ්‍යාපනය ලබාදීම, විනෝදාස්වාදය සහ මත සම්පාදනය (අධීක්ෂණය)", "බදු අය කිරීම, නඩු ඇසීම, සිරගත කිරීම හා යුද කිරීම", "මුදල් අච්චු ගැසීම හා වීසා දීම", "ඡන්ද පත්‍රිකා ගණන් කිරීම", "මාධ්‍යය සමාජයේ දැනුම හා සංස්කෘතිය පෝෂණය කරන ප්‍රබලතම සමාජ ආයතනයකි."),
    q("යම් ප්‍රවෘත්ති වාර්තාවක් හෝ ඡායාරූපයක් 'කෘත්‍රිම බුද්ධියෙන් (AI) හෝ Photoshop මගින් සංස්කරණය කළ එකක්දැයි' සැක සිතුණු විට කළ යුත්තේ කුමක්ද?", "ප්‍රතිලෝම රූප සෙවුම (Reverse Image Search) හා නිල පුවත් ආයතන පරීක්ෂා කිරීම", "සත්‍ය යැයි සිතා වහාම Share කිරීම", "වෙනත් බොරු කතාවක් එයට එකතු කිරීම", "මුද්‍රණය කර පාරේ ඇලවීම", "තාක්ෂණික මෙවලම් භාවිතයෙන් රූප හා වීඩියෝවල මුල් මූලාශ්‍රය තහවුරු කරගත හැකිය."),
    q("රටේ පාර්ලිමේන්තු විවාද සහ තේරීම් කාරක සභා රැස්වීම් රූපවාහිනියෙන් හා අන්තර්ජාලයෙන් 'සජීවීව විකාශනය කිරීම' ප්‍රජාතන්ත්‍රවාදයට වැදගත් වන්නේ ඇයි?", "මන්ත්‍රීවරුන් ජනතා ප්‍රශ්න ගැන දක්වන ස්ථාවරය හා හැසිරීම පුරවැසියන්ට සෘජුව දැක බලා ගැනීමට හැකි වීමෙන්", "විවාද නැවැත්වීමට", "රූපවාහිනී නාලිකා වැසීමට", "පාර්ලිමේන්තුව රහසිගත කිරීමට", "මහජන නියෝජිතයන්ගේ වගවීම ඉහළ නැංවීමට සජීවී විකාශන විශාල මෙහෙයක් ඉටු කරයි."),
    q("ශ්‍රී ලංකාවේ 'ජාතික චිත්‍රපට සංස්ථාව හා ප්‍රසිද්ධ රැඟුම් පාලක මණ්ඩලය' මඟින් සිනමා හා නාට්‍ය ක්ෂේත්‍රයේදී සිදු කරන්නේ කුමක්ද?", "සිනමා කර්මාන්තය දිරිගැන්වීම හා ප්‍රසිද්ධ ප්‍රදර්ශනයට පෙර වයස් සීමා හා ආචාරධර්ම පරීක්ෂා කිරීම", "පුවත්පත් කතුවැකි ලිවීම", "පළාත් සභා බදු අය කිරීම", "මැතිවරණ පෙත්සම් විභාග කිරීම", "ළමුන්ට හා සමාජ සංහිඳියාවට හානි නොවන පරිදි කලා නිර්මාණ වර්ගීකරණය කිරීම මෙහිදී කෙරේ."),
    q("රටක 'මාධ්‍ය වාර්තාකරණයේදී පුද්ගල පෞද්ගලිකත්වය' (Right to Privacy) සීමා කළ නොහැකි අවස්ථාවක් වන්නේ කුමක්ද?", "මහජන අරමුදල්වලට හෝ රාජ්‍ය රාජකාරියට කිසිදු සම්බන්ධයක් නැති පුද්ගලයෙකුගේ පෞද්ගලික පවුල් ජීවිතය", "ඇමතිවරයෙකුගේ රාජ්‍ය මුදල් වියදම", "පළාත් පාලන ටෙන්ඩර් වංචාවක්", "මහජන සෞඛ්‍යයට තර්ජනයක් වන ආහාර වංචාවක්", "මහජන යහපතට අදාළ නොවන පෞද්ගලික රහස් අලෙවි කිරීමේ පටු අරමුණින් හෙළි කිරීම මාධ්‍ය ආචාරධර්මවලට විරුද්ධය."),
    q("සමාජ මාධ්‍ය තුළ 'සත්‍ය තොරතුරු බෙදාගැනීමේදී' හා සංවාද කිරීමේදී පිළිපැදිය යුතු ඩිජිටල් ආචාරධර්ම (Netiquette) මොනවාද?", "වෙනත් අයගේ අදහස්වලට ගරු කිරීම, කුණුහරුප හෝ අපහාස නොකිරීම හා නිවැරදි තොරතුරු පමණක් පළ කිරීම", "ව්‍යාජ ගිණුම්වලින් තර්ජනය කිරීම", "අන් අයගේ ඡායාරූප විකෘති කිරීම", "වෛරී අදහස් පළ කිරීම", "ඩිජිටල් අවකාශයේදීද සැබෑ ලෝකයේ මෙන්ම ශිෂ්ටසම්පන්න හා ගෞරවනීය හැසිරීමක් තිබිය යුතුය."),
    q("පුවත්පත් කලාවේදයේ 'නිර්භීත හා ස්වාධීන කතුවැකි' පළ කිරීමෙන් රටේ පාලනයට ඇති වන යහපත කුමක්ද?", "රජයේ වැරදි ප්‍රතිපත්ති පෙන්වා දී ජනහිතකාමී සංශෝධන සිදු කිරීමට පාලකයන් පෙළඹවීම", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "රජයේ බැංකු වැසී යාම", "නීතිඥ සංගමය අහෝසි වීම", "විවේචනය සතුරුකමක් ලෙස නොව පාලනය නිවැරදි කර ගැනීමේ මාර්ගෝපදේශයක් ලෙස ප්‍රජාතන්ත්‍රවාදී නායකයෝ සලකති."),
    q("ජනමාධ්‍ය හා මහජන මතය අතර පවතින 'න්‍යාය පත්‍ර සැකසීමේ' (Agenda-Setting) බලය යනු කුමක්ද?", "මාධ්‍ය නිරන්තරයෙන් අවධානය යොමු කරන ගැටලු පොදු ජනතාවගේ හා පාලකයන්ගේ ප්‍රමුඛතා බවට පත්වීම", "රජයේ කාර්යාල නිවාඩු ලැයිස්තුව සෑදීම", "පාසල් කාලසටහන් මුද්‍රණය", "රේගු බදු ලේඛනය", "එබැවින් ජනමාධ්‍ය හරසුන් පුවත් වෙනුවට අධ්‍යාපන, ආර්ථික හා පාරිසරික ගැටලුවලට ප්‍රමුඛතාව දිය යුතුය."),
    q("රටේ ආපදා කාලවලදී 'රාජ්‍ය විද්‍යුත් මාධ්‍ය හා ප්‍රජා ගුවන්විදුලි' එක්ව සිදු කරන ප්‍රධාන මෙහෙය කුමක්ද?", "විපතට පත් ප්‍රදේශවලට අවශ්‍ය වියළි ආහාර, ඖෂධ හා බේරාගැනීමේ කණ්ඩායම් සම්බන්ධීකරණය කිරීම", "ආපදා ආධාර මුදල් අවභාවිත කිරීම", "වැරදි සුනාමි කටකතා පැතිරවීම", "මධ්‍යස්ථාන වසා දැමීම", "මානුෂීය ආපදා වාර්තාකරණය ජීවිත බේරා ගැනීමේ ජාතික මෙහෙයුමක කොටසකි."),
    q("මහජන මතයක් සමාජය තුළ ශක්තිමත් වී නීතියක් බවට පත් වූ අවස්ථාවකට උදාහරණයක් වන්නේ කුමක්ද?", "මාධ්‍යවේදීන්ගේ හා සිවිල් සංවිධානවල දිගුකාලීන ඉල්ලීම් මත 2016 තොරතුරු දැනගැනීමේ පනත සම්මත වීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීම", "නිදහස් අධ්‍යාපනය නතර කිරීම", "වෘත්තීය සමිති තහනම් කිරීම", "සංවිධානාත්මක මහජන මතය හා සිවිල් සමාජ අරගල ප්‍රගතිශීලී නීති බිහි කිරීමට මග පාදයි."),
    q("ශ්‍රී ලංකාවේ 'වැඩිහිටියන් හා කාන්තාවන් ඉලක්ක කරගත් මාධ්‍ය ප්‍රචාරණයන්හිදී' වළක්වා ගත යුතු සදාචාර විරෝධී ක්‍රියාව කුමක්ද?", "කාන්තාවන් වෙළඳ භාණ්ඩයක් ලෙස හෝ පහත් ඒකාකෘති (Stereotypes) ලෙස නිරූපණය කිරීම", "කාන්තා ව්‍යවසායකයන් අගය කිරීම", "සාර්ථක ක්‍රීඩිකාවන් ගැන වාර්තා කිරීම", "අධ්‍යාපන ශිෂ්‍යත්ව ගැන දැන්වීම", "ස්ත්‍රී පුරුෂ ගරුත්වය ආරක්ෂා කිරීම ගුණාත්මක ජනමාධ්‍ය සංස්කෘතියක ලක්ෂණයකි."),
    q("තොරතුරු තාක්ෂණය දියුණු වත්ම මුද්‍රිත පුවත්පත් පවා තම අනන්‍යතාව රැක ගැනීමට ගෙන ඇති නවීන පියවර කුමක්ද?", "E-paper, පුවත් වෙබ් අඩවි හා සමාජ මාධ්‍ය සජීවී විකාශන සමඟ ඒකාබද්ධ වීම", "සියලු ප්‍රවෘත්ති ලිවීම නැවැත්වීම", "පුවත්පත් ගිනි තැබීම", "පාඨකයන්ට ප්‍රවෘත්ති තහනම් කිරීම", "මාධ්‍ය අභිසාරීතාව (Media Convergence) හරහා මුද්‍රිත, විද්‍යුත් හා ඩිජිටල් වේදිකා එකට එක් වී ඇත."),
    q("සමාජ මාධ්‍ය වේදිකාවක 'දෙපියවර සත්‍යාපනය' (Two-Factor Authentication - 2FA) සක්‍රීය කිරීමෙන් ලැබෙන ආරක්ෂාව කුමක්ද?", "මුරපදය වෙනත් අයෙකු දැනගත්තද දුරකථන සත්‍යාපන කේතය නොමැතිව ගිණුමට ඇතුළු වීම වැළැක්වීම", "පුවත් ස්වයංක්‍රීයව බොරු වීම", "අන්තර්ජාල ගාස්තුව ශුන්‍ය වීම", "සියලු මිතුරන් ඉවත් වීම", "සයිබර් අපරාධකරුවන්ගෙන් තම ඩිජිටල් අනන්‍යතාව ආරක්ෂා කර ගැනීමට 2FA ඉතා වැදගත් වේ."),
    q("රටේ පාසල් සිසුන් අතර 'පුවත්පත් හා පුස්තකාල පරිහරණය' දියුණු කිරීමෙන් ගොඩනැගෙන ප්‍රධාන පුරවැසි ගුණාංගය කුමක්ද?", "ගැඹුරු කියවීම, විශ්ලේෂණාත්මක චින්තනය හා සමබර දැනුම", "සමාජ මාධ්‍ය කටකතාවලට පමණක් සීමා වීම", "අන් අයගේ මත ප්‍රතික්ෂේප කිරීම", "භාෂා දැනුම දුර්වල වීම", "සාරවත් කියවීම හා පර්යේෂණාත්මක මනසක් ඇති පුරවැසියා ප්‍රජාතන්ත්‍රවාදයේ සැබෑ ආභරණයකි."),
    q("වෙළඳ දැන්වීම් හා මාධ්‍ය ප්‍රචාර මගින් පාරිභෝගිකයන් තුළ ඇති කරන 'අනවශ්‍ය පරිභෝගිකවාදය' (Consumerism) ජය ගන්නේ කෙසේද?", "අවශ්‍යතාව (Needs) සහ ආශාව (Wants) අතර වෙනස හඳුනාගෙන අරපිරිමැස්මෙන් තීරණ ගැනීමෙන්", "දැන්වීම්වල ඇති සියල්ල ණයට මිලදී ගැනීමෙන්", "පවුලේ ඉතිරි කිරීම් සියල්ල වැය කිරීමෙන්", "පරිසරයට ප්ලාස්ටික් එක් කිරීමෙන්", "මාධ්‍ය සාක්ෂරතාව පුද්ගලික මූල්‍ය විනය හා තිරසාර ජීවන රටාව සඳහාද ඍජුවම උපකාරී වේ."),
    q("සිවිල් සමාජය සහ මාධ්‍ය එක්ව රජයට 'ප්‍රතිපත්ති උපදේශනය' (Policy Advocacy) සිදු කිරීමේ ප්‍රධාන ආකාරය කුමක්ද?", "පර්යේෂණ වාර්තා, ප්‍රසිද්ධ සංවාද, කතුවැකි හා පාර්ලිමේන්තු කාරක සභා යෝජනා ඉදිරිපත් කිරීම", "රජයේ කාර්යාල ගිනි තැබීම", "පාසල් සිසුන්ගේ පොත් ඉරා දැමීම", "බදු නොගෙවා සැඟවී සිටීම", "සාක්ෂි සහිත සංවාදාත්මක මැදිහත්වීම මඟින් වඩාත් ජනහිතකාමී නීති සම්පාදනයට සහාය විය හැක."),
    q("පුවත්පතක් හෝ රූපවාහිනී නාලිකාවක් 'වැරදි පුවතක් ප්‍රචාරය වූ බව දැනගත් විගස' කළ යුතු ආචාරධර්මීය ක්‍රියාව කුමක්ද?", "එම වැරදි පුවත ඉවත් කර ප්‍රසිද්ධියේ සමාව ගෙන නිවැරදි කරුණ පළ කිරීම (Corrigendum)", "වැරැද්ද සඟවා දිගටම තබා ගැනීම", "පාඨකයාට බැණ වැදීම", "වෙනත් බොරුවක් පළ කිරීම", "වැරදි නිවැරදි කිරීම මාධ්‍ය ආයතනයක වෘත්තීය අවංකභාවය හා විශ්වසනීයත්වය වැඩි කරයි."),
    q("ජනමාධ්‍ය තුළ 'සංවේදී අපරාධ හා හදිසි අනතුරු' ඡායාරූප පළ කිරීමේදී මාධ්‍යවේදීන් සීමා පනවා ගත යුත්තේ ඇයි?", "මියගිය හෝ තුවාල වූ අයගේ මානව ගරුත්වය රැකීමට හා පවුලේ අයට සිදුවන කම්පනය අඩු කිරීමට", "කැමරා උපකරණ අඩු බැවින්", "ඡායාරූප ගැනීමට නොදන්නා බැවින්", "වෙළඳ දැන්වීම් වැඩි කිරීමට", "ලේ වැකි දර්ශන විකිණීමට වඩා මානව සංවේදීතාව හා ගෞරවය මාධ්‍ය ආචාරධර්මයේ ඉහළින්ම සැලකේ."),
    q("අධ්‍යාපනික මාධ්‍ය වැඩසටහන් මඟින් ශ්‍රී ලංකාවේ 'විවිධ සංස්කෘතීන් හා භාෂාවන්' පිළිබඳව අවබෝධය ලබාදීම වැදගත් වන්නේ ඇයි?", "එකිනෙකාගේ භාෂා හා සංස්කෘතීන් අගය කරන සමගිසම්පන්න පුරවැසි සමාජයක් බිහි කිරීමට", "වෙනත් භාෂා ඉගෙනීම නැවැත්වීමට", "සියලු උත්සව තහනම් කිරීමට", "රූපවාහිනිය වසා දැමීමට", "ත්‍රෛභාෂා ගෞරවය හා සංස්කෘතික සංවේදීතාව පෝෂණය කිරීම ජනමාධ්‍යයේ උදාර මෙහෙවරකි."),
    q("රටේ පුරවැසියන්ට 'නිවැරදි ආර්ථික හා කාලගුණික තොරතුරු' දිනපතා මාධ්‍ය ඔස්සේ ලැබීම වැදගත් වන්නේ කෙසේද?", "ගොවීන්ට, ධීවරයන්ට හා ව්‍යාපාරිකයන්ට තම ආරක්ෂාව හා නිෂ්පාදන සැලසුම් සකස් කර ගැනීමට", "ධීවරයන්ට මුහුදු යාම සම්පූර්ණයෙන් තහනම් කිරීමට", "කෘෂිකර්මාන්තය නතර කිරීමට", "වෙළඳපොළ වසා දැමීමට", "නිවැරදි තොරතුරු ප්‍රවාහය පුද්ගලික ජීවිතය මෙන්ම ජාතික ආර්ථිකයද සුරක්ෂිත කරයි."),
    q("ප්‍රජාතන්ත්‍රවාදී සමාජයක 'අදහස් ප්‍රකාශ කිරීමේ නිදහස' රැකගැනීම සඳහා පුරවැසියෙකු සතු වගකීම කුමක්ද?", "තමන් අකමැති වුවද අන් අයගේ සාමකාමී මතය ප්‍රකාශ කිරීමේ අයිතියට ගරු කිරීම", "විරුද්ධ මත දරන්නන්ට පහර දීම", "සියලු පුවත්පත් ගිනි තැබීම", "අසත්‍ය කටකතා නිර්මාණය කිරීම", "අනුන්ගේ මත ඉවසීම (Tolerance) භාෂණයේ නිදහස සුරක්ෂිත කරන මූලික ප්‍රජාතන්ත්‍රවාදී ගුණාංගයයි."),
    q("මාධ්‍ය හරහා තරුණ පරපුරට 'නවෝත්පාදන හා ව්‍යවසායකත්ව' ආදර්ශ චරිත හඳුන්වා දීමෙන් සමාජයට සිදුවන යහපත කුමක්ද?", "සමාජ ප්‍රශ්නවලට නිර්මාණශීලී විසඳුම් සොයන ආත්ම විශ්වාසයෙන් යුත් තරුණ නායකයන් බිහිවීම", "තරුණයන් සියල්ල අධෛර්යමත් වීම", "වැඩ ලෝකයෙන් ඉවත් වීම", "අධ්‍යාපනය අත්හැරීම", "ධනාත්මක ආදර්ශ සමාජය ඉදිරියට ගෙන යන ප්‍රබල මාධ්‍ය බලවේගයකි."),
    q("පුවත්පත් වාර්තාවක 'මූලාශ්‍ර සඳහන් නොකර අන් අයගේ ප්‍රකාශ විකෘති කිරීම' මගින් සිදුවන්නේ කුමක්ද?", "මාධ්‍ය වෘත්තීයභාවය හා මහජන විශ්වාසය බරපතළ ලෙස පළුදු වීම", "පුවත්පතේ අගය ඉහළ යාම", "නීතිමය සම්මාන ලැබීම", "වැරදි අඩු වීම", "සන්දර්භයෙන් පිටත උපුටා දැක්වීම් (Misquoting) නොකර නිවැරදි අර්ථය පළ කිරීම මාධ්‍ය වගකීමයි."),
    q("නව මාධ්‍ය යුගයේදී 'පවුල් තුළ මාධ්‍ය භාවිතය' සෞඛ්‍ය සම්පන්නව කළමනාකරණය කර ගන්නේ කෙසේද?", "දෙමාපියන් හා දරුවන් එක්ව තිර කාලය (Screen Time) සීමා කර නිර්මාණශීලී අධ්‍යාපනික දේ තෝරාගැනීමෙන්", "කුඩා දරුවන්ට පැය 24ම අන්තර්ජාලය භාවිතයට ඉඩ දීමෙන්", "පවුලේ සංවාද සම්පූර්ණයෙන් නැවැත්වීමෙන්", "පොත් කියවීම තහනම් කිරීමෙන්", "සමබර තාක්ෂණ භාවිතය පවුල් බැඳීම් හා දරුවන්ගේ මානසික සෞඛ්‍යය රැකගනී."),
    q("ශ්‍රී ලංකාවේ මාධ්‍ය ආයතන, වෘත්තීය සමිති හා ප්‍රජා සංවිධාන යහපාලන සමාජයක ඉටු කරන පොදු මෙහෙවර කුමක්ද?", "වගවීම, සමාජ සාධාරණත්වය, කම්කරු අයිතීන් හා නිවැරදි මහජන මතය පෝෂණය කිරීම", "රාජ්‍ය ආයතන කඩාකප්පල් කිරීම", "ව්‍යාජ පුවත් නිපදවීම", "වැඩ වර්ජන පමණක් පැවැත්වීම", "සිවිල් අවකාශයේ මෙම ආයතන සියල්ල එක්ව ප්‍රජාතන්ත්‍රවාදී රාජ්‍ය පාලනය ශක්තිමත් කරයි.")
  )
}

